import{_ as t,o as a,c as o,a0 as r}from"./chunks/framework.BxrwG5q5.js";const g=JSON.parse('{"title":"Percentage Rollouts","description":"","frontmatter":{},"headers":[],"relativePath":"features/rollouts.md","filePath":"features/rollouts.md"}'),i={name:"features/rollouts.md"};function l(s,e,n,u,h,d){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="percentage-rollouts" tabindex="-1">Percentage Rollouts <a class="header-anchor" href="#percentage-rollouts" aria-label="Permalink to &quot;Percentage Rollouts&quot;">​</a></h1><blockquote><p>See also: <a href="/config/features/targeting.html">Targeting Rules</a> · <a href="/config/features/segments.html">Segments</a> · <a href="/config/features/environments.html">Environments</a></p></blockquote><p>Gradually release features to a percentage of users. Start with 5%, validate, then increase to 20%, 50%, and finally 100%. Rollouts are evaluated after <a href="/config/features/targeting.html">targeting rules</a> in the pipeline.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><ol><li>Set a <strong>rollout percentage</strong> (0–100) on any config</li><li>Set the <strong>rollout value</strong> (what users in the rollout get)</li><li>Users are bucketed deterministically: same user always gets the same result</li></ol><h2 id="deterministic-bucketing" tabindex="-1">Deterministic Bucketing <a class="header-anchor" href="#deterministic-bucketing" aria-label="Permalink to &quot;Deterministic Bucketing&quot;">​</a></h2><p>Rollouts use a MurmurHash3 algorithm: <code>hash(flagKey + &quot;:&quot; + userId) % 100</code>. This means:</p><ul><li>The same user always gets the same bucket for a given flag</li><li>Different flags give the same user different buckets (independent rollouts)</li><li>No session storage or cookies required — purely based on userId</li></ul><h2 id="setting-up-a-rollout" tabindex="-1">Setting Up a Rollout <a class="header-anchor" href="#setting-up-a-rollout" aria-label="Permalink to &quot;Setting Up a Rollout&quot;">​</a></h2><ol><li>Open a config in the portal</li><li>Expand the <strong>Rollout</strong> section</li><li>Set the percentage (e.g., 20)</li><li>Set the rollout value (e.g., <code>true</code> for a boolean flag)</li><li>Save</li></ol><h2 id="what-happens-when-you-change-the-percentage" tabindex="-1">What Happens When You Change the Percentage? <a class="header-anchor" href="#what-happens-when-you-change-the-percentage" aria-label="Permalink to &quot;What Happens When You Change the Percentage?&quot;">​</a></h2><p>Since bucketing is deterministic (<code>hash % 100</code>), changing the percentage does <strong>not</strong> re-randomize users:</p><table tabindex="0"><thead><tr><th>Change</th><th>Effect</th></tr></thead><tbody><tr><td>20% → 50%</td><td>All users who were in the 20% bucket remain in the rollout. An additional ~30% of users are added (those with buckets 20–49).</td></tr><tr><td>50% → 20%</td><td>Users with buckets 20–49 are removed from the rollout. Users with buckets 0–19 remain.</td></tr><tr><td>100% → 0%</td><td>Everyone reverts to the default value.</td></tr></tbody></table><p><strong>Key insight:</strong> Increasing the percentage is always additive — existing users never lose the feature when you ramp up. Decreasing the percentage does remove users from the high end of the bucket range.</p><div class="tip custom-block"><p class="custom-block-title">Ramp-up is safe</p><p>You can confidently go 5% → 10% → 25% → 50% → 100% knowing that the first 5% of users remain consistent throughout the entire ramp-up.</p></div><h2 id="rollout-targeting" tabindex="-1">Rollout + Targeting <a class="header-anchor" href="#rollout-targeting" aria-label="Permalink to &quot;Rollout + Targeting&quot;">​</a></h2><p>Targeting rules have higher priority than rollouts in the evaluation pipeline. If a targeting rule matches, the rollout is skipped. This means you can:</p><ul><li>Target &quot;Enterprise Users&quot; → always get the feature</li><li>Roll out to 20% of everyone else → gradual release</li></ul><p>See <a href="/config/features/segments.html">Segments</a> for creating reusable audience groups to combine with rollouts.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>A <code>userId</code> must be provided in the SDK context for rollout to work</li><li>Without a userId, rollout is skipped and the default value is returned</li><li>The userId should be stable (don&#39;t use random session IDs)</li></ul><h2 id="consistency-across-modes" tabindex="-1">Consistency Across Modes <a class="header-anchor" href="#consistency-across-modes" aria-label="Permalink to &quot;Consistency Across Modes&quot;">​</a></h2><p>The same hashing algorithm is used in both server-side evaluation (client keys) and client-side evaluation (server keys). A user bucketed at 30% in one mode will be bucketed at 30% in the other — no flip-flopping during migration.</p><h2 id="edge-cases" tabindex="-1">Edge Cases <a class="header-anchor" href="#edge-cases" aria-label="Permalink to &quot;Edge Cases&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Behavior</th></tr></thead><tbody><tr><td><code>rolloutPercentage: 0</code></td><td>Rollout step is skipped entirely; pipeline continues to default</td></tr><tr><td><code>rolloutPercentage: 100</code></td><td>Everyone gets the rollout value (equivalent to changing the default)</td></tr><tr><td>No <code>userId</code> in context</td><td>Rollout step is skipped; pipeline continues to default</td></tr><tr><td>Same user, different flags</td><td>Different buckets (the flag key is part of the hash input)</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/config/features/targeting.html">Targeting Rules</a> — Targeting rules take priority over rollouts in evaluation</li><li><a href="/config/features/segments.html">Segments</a> — Define audience groups to combine with percentage rollouts</li><li><a href="/config/features/environments.html">Environments</a> — Roll out independently per environment</li><li><a href="/config/features/audit-log.html">Audit Log</a> — Track rollout percentage changes over time</li><li><a href="/config/guide/scopes.html">Configuration Scopes</a> — Understand the full evaluation pipeline</li></ul>',27)])])}const p=t(i,[["render",l]]);export{g as __pageData,p as default};
